const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeOkeechobee = ee.Geometry.Polygon([
    [-80.9, 27.2], [-80.6, 27.2], [-80.6, 26.9], [-80.9, 26.9], [-80.9, 27.2]
  ]);

  const targetDate = '2023-06-12';

  // 2. Data Acquisition - Sentinel-2 for cyanobacteria detection
  let s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeOkeechobee)
    .filterDate(targetDate, ee.Date(targetDate).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

  const colSize = s2Col.size().getInfo();
  console.log(`Sentinel-2 images on ${targetDate}: ${colSize}`);

  if (colSize === 0) {
    console.log("No Sentinel-2 data found for target date");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get best image and mask clouds
  const image = s2Col.first();

  // Cloud masking using QA60 band
  const cloudBitMask = 1 << 10;
  const cirrusBitMask = 1 << 11;
  const qa = image.select('QA60');
  const cloudMask = qa.bitwiseAnd(cloudBitMask).eq(0)
    .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

  const maskedImage = image.updateMask(cloudMask);

  // 4. Cyanobacteria detection using NDCI (Normalized Difference Chlorophyll Index)
  const ndci = maskedImage.normalizedDifference(['B5', 'B4']).rename('NDCI');

  // Threshold for cyanobacteria detection (adjustable based on validation)
  const cyanobacteriaThreshold = 0.1;
  const cyanobacteriaMask = ndci.gt(cyanobacteriaThreshold);

  // 5. Calculate coverage statistics
  const cyanobacteriaStats = cyanobacteriaMask.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: lakeOkeechobee,
    scale: 20,
    maxPixels: 1e9
  });

  const cyanPixels = cyanobacteriaStats.get('NDCI_sum').getInfo();
  const totalPixels = cyanobacteriaStats.get('NDCI_count').getInfo();

  console.log(`Cyanobacteria pixels: ${cyanPixels}`);
  console.log(`Total valid pixels: ${totalPixels}`);

  if (totalPixels === 0) {
    console.log("No valid pixels after processing");
    console.log("<answer>C2</answer>");
    return;
  }

  const coveragePercent = (cyanPixels / totalPixels) * 100;
  console.log(`Cyanobacteria coverage: ${coveragePercent.toFixed(2)}%`);

  // 6. Validation & Final Answer
  if (coveragePercent === null || coveragePercent === undefined || 
      isNaN(coveragePercent) || coveragePercent < 0 || coveragePercent > 100) {
    console.log("<answer>C3</answer>");
  } else if (coveragePercent > 30) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
